import weaviate

client = weaviate.connect_to_local()

if not client.collections.exists("{{collection_name}}"):
    client.collections.create("{{collection_name}}")

col = client.collections.get("{{collection_name}}")

def add(text: str, vec: list[float]):
    col.data.insert(properties={"text": text}, vector=vec)

def search(vec: list[float], k: int = 5):
    return col.query.near_vector(near_vector=vec, limit=k).objects
